        return (1);
    sf->var_norm.time_wave = 335;
    return (0);
}

void change_cursor(variable_t *sf, int status)
{
    static int display = 1;
    sfVector2i mouse = sfMouse_getPositionRenderWindow(sf->win.dow);
    sfVector2f pos_m = {mouse.x * 1.0 - (23 / 2), mouse.y * 1.0 - (32.5 / 2)};
    sfIntRect rect;

    if (status == 0)
        display = 0;
    if (status == 1)
        display = 1;
